/* Shared justified-grid + PhotoSwipe lightbox wiring for for-fun.qmd.
 *
 * Renders a fjGallery-justified grid of lazy-loaded, srcset/sizes thumbnails
 * (AVIF -> WebP -> JPEG fallback) from a manifest generated by
 * scripts/generate-gallery-derivatives.py, and opens a PhotoSwipe lightbox on
 * click that only fetches medium/original-resolution sources once opened
 * (via data-pswp-srcset, originals as the largest candidate).
 *
 * Depends on globals from vendored scripts loaded earlier on the page:
 * fjGallery, PhotoSwipeLightbox, PhotoSwipe.
 */
(function () {
  "use strict";

  var MANIFEST_URL = "assets/gallery-derivatives/manifest.json";
  var manifestPromise = null;

  function loadManifest() {
    if (!manifestPromise) {
      manifestPromise = fetch(MANIFEST_URL).then(function (res) {
        if (!res.ok) throw new Error("gallery manifest fetch failed: " + res.status);
        return res.json();
      });
    }
    return manifestPromise;
  }

  function escapeHtml(str) {
    return String(str).replace(/[&<>"']/g, function (c) {
      return { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c];
    });
  }

  function itemMarkup(item) {
    var cap = item.caption || "";
    var alt = cap || "Photograph";
    var capAttr = cap ? ' data-caption="' + escapeHtml(cap) + '"' : "";

    return (
      '<a class="gallery-item" href="' + item.full.src + '"' +
        capAttr +
        ' data-pswp-srcset="' + escapeHtml(item.full.srcset) + '"' +
        ' data-pswp-width="' + item.width + '"' +
        ' data-pswp-height="' + item.height + '"' +
      '>' +
        '<picture>' +
          '<source type="image/avif" srcset="' + escapeHtml(item.thumb.avifSrcset) + '">' +
          '<source type="image/webp" srcset="' + escapeHtml(item.thumb.webpSrcset) + '">' +
          '<img src="' + item.thumb.fallbackSrc + '"' +
            ' srcset="' + escapeHtml(item.thumb.fallbackSrcset) + '"' +
            ' sizes="(max-width: 600px) 45vw, (max-width: 1000px) 30vw, 320px"' +
            ' width="' + item.width + '" height="' + item.height + '"' +
            ' alt="' + escapeHtml(alt) + '"' +
            ' loading="lazy" decoding="async">' +
        '</picture>' +
        '<span class="gallery-hover-icon"><i class="fa-solid fa-magnifying-glass-plus"></i></span>' +
      '</a>'
    );
  }

  // Registered once per lightbox instance; reads the caption straight off
  // the triggering <a>'s data-caption attribute set in itemMarkup() above.
  function registerCaption(lightbox) {
    lightbox.on("uiRegister", function () {
      lightbox.pswp.ui.registerElement({
        name: "custom-caption",
        order: 9,
        isButton: false,
        appendTo: "root",
        tagName: "div",
        className: "pswp__custom-caption",
        onInit: function (el) {
          lightbox.pswp.on("change", function () {
            var slideEl = lightbox.pswp.currSlide && lightbox.pswp.currSlide.data.element;
            el.textContent = (slideEl && slideEl.dataset.caption) || "";
          });
        },
      });
    });
  }

  function rowHeightFor(container) {
    var w = window.innerWidth;
    var base = parseInt(container.dataset.rowHeight, 10) || 200;
    var md = parseInt(container.dataset.rowHeightMd, 10) || base;
    var sm = parseInt(container.dataset.rowHeightSm, 10) || md;
    if (w < 600) return sm;
    if (w < 1000) return md;
    return base;
  }

  function initGallery(container, items) {
    container.innerHTML = items.map(itemMarkup).join("");

    var fjg = fjGallery(container, {
      itemSelector: ".gallery-item",
      rowHeight: rowHeightFor(container),
      gutter: 10,
      lastRow: "left",
      rowHeightTolerance: 0.25,
      onJustify: function () { container.classList.add("is-ready"); },
    });

    var lightbox = new PhotoSwipeLightbox({
      gallery: container,
      children: ".gallery-item",
      pswpModule: PhotoSwipe,
      showHideAnimationType: "zoom",
      bgOpacity: 0.9,
    });
    registerCaption(lightbox);
    lightbox.init();

    var lastRowHeight = rowHeightFor(container);
    var resizeTimer;
    window.addEventListener("resize", function () {
      clearTimeout(resizeTimer);
      resizeTimer = setTimeout(function () {
        var next = rowHeightFor(container);
        if (next !== lastRowHeight) {
          lastRowHeight = next;
          fjGallery(container, "updateOptions", { rowHeight: next });
        }
      }, 200);
    });

    return { fjg: fjg, lightbox: lightbox };
  }

  function initAll() {
    var containers = document.querySelectorAll("[data-gallery]");
    if (!containers.length) return;

    loadManifest()
      .then(function (manifest) {
        containers.forEach(function (container) {
          var key = container.dataset.gallery;
          var items = (manifest.galleries && manifest.galleries[key]) || [];
          if (!items.length) return;
          initGallery(container, items);
        });
      })
      .catch(function (err) {
        console.error("gallery init failed:", err);
        containers.forEach(function (c) { c.classList.add("is-ready"); });
      });
  }

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", initAll);
  } else {
    initAll();
  }
})();
